layer.css:
@import url("https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600;700&family=DM+Sans:wght@400;500;700&family=Libre+Baskerville:wght@400;700&display=swap");
[data-ryt="pitch"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="footer"] { color: var(--ryt-text); border-top: 1px solid var(--ryt-border); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 11.2px; box-shadow: rgba(37, 26, 14, 0.08) 0px 14px 30px 0px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: rgb(109, 42, 36); background-color: rgb(245, 239, 228); border-top: 1px solid rgb(183, 148, 135); border-right: 1px solid rgb(183, 148, 135); border-bottom: 1px solid rgb(183, 148, 135); border-left: 1px solid rgb(183, 148, 135); border-radius: 999px; font-family: "DM Sans", "Segoe UI", sans-serif; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: 0.96px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(109, 42, 36); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4.8px; padding-right: 9.92px; padding-bottom: 4.8px; padding-left: 9.92px; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: 0.504px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 40px; font-weight: 600; font-style: normal; line-height: 1.7; letter-spacing: 0.96px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="header"] { background-image: linear-gradient(rgb(244, 237, 225), var(--ryt-bg)); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-bottom: 1px solid var(--ryt-border); border-top: none }
[data-ryt="nav"] a { color: var(--ryt-muted); border-radius: 0px; font-family: "DM Sans", "Segoe UI", sans-serif; font-size: 13.76px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: 1.2384px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 3.2px; padding-right: 0px; padding-bottom: 3.2px; padding-left: 0px; transition: all; position: relative }
[data-ryt="button"] { color: var(--ryt-text); background-color: var(--ryt-surface); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 999px; font-family: "DM Sans", "Segoe UI", sans-serif; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: 0.9984px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 7.04px; padding-right: 12.16px; padding-bottom: 7.04px; padding-left: 12.16px; transition: all }
[data-ryt="review"] { color: var(--ryt-muted); font-family: var(--ryt-font-body); font-size: 15.2px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: "DM Sans", "Segoe UI", sans-serif; font-size: 12px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: 0.96px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="cover"] { border-radius: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: 0.288px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 28.8px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: 0.288px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #1e1a16 }
[data-ryt="cover"]:hover { transform: scale(1.03) }
[data-ryt="nav"] a::after { content: ""; display: block; position: absolute; width: 100%; height: 1px; color: var(--ryt-muted); background-color: var(--ryt-accent); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: "DM Sans", "Segoe UI", sans-serif; font-size: 13.76px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: 1.2384px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: transform 0.22s; -webkit-text-fill-color: var(--ryt-muted); bottom: -3.2px; left: 0px }
[data-ryt="nav"] a:hover { color: #1e1a16; color: #1e1a16 }
[data-ryt="brand"]:hover { color: #1e1a16 }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { color: #1e1a16; color: #1e1a16 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #1e1a16 }
